Q: Efficient algorithm for solving a Letter Boxed–style word game A: <p>There are 26 letters in the English alphabet, so this problem can never be larger than a box with 7 letters on each side.</p>
<p>This seems quite tiny. ( I am accustomed to tackling graph theory problems with hundreds of thousands of edges. )</p>
<p>What performance are YOU getting?</p>
<p>==========</p>
<p>FYI I have spun up some quick and dirty code that does a brute force search for the solution to these problems.  For a moderately sized problem with 3 letters per box side, it finds a decent solution in less than 1/10th of a second.  Do you really need anything faster than this?</p>
<p>Example:</p>
<p><img src="https://i.sstatic.net/Yec1N5x7.png" alt="enter image description here" /></p>
<p>Solution: <strong>afront tick kelp</strong></p>
<p>Processing time, including reading dictionary: <strong>0.02 seconds</strong></p>
<p>Complete project: <a href="https://codeberg.org/JamesBremner/LetterBoxSolver" rel="nofollow noreferrer">https://codeberg.org/JamesBremner/LetterBoxSolver</a></p>
<p>Source code:</p>
<pre><code>C++
#include &lt;string&gt;
#include &lt;fstream&gt;
#include &lt;sstream&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;set&gt;
#include &lt;algorithm&gt;
#include &quot;cRunWatch.h&quot;

using chain_t = std::vector&lt;std::string&gt;;

std::vector&lt;std::string&gt; letterBox;
std::string allLetters;
std::vector&lt;std::string&gt; dict;

class chain
{
public:
    bool start(const std::string &amp;start);

private:
    bool recurse();
    bool hasAll();
    void used();
    bool isUsedLetterInWord(const std::string &amp;word);

    chain_t myChain;
    std::set&lt;char&gt; myUsed;
};

chain theChain;

void getAllLetters()
{
    for (auto &amp;e : letterBox)
    {
        for (auto &amp;c : e)
            c = std::tolower(c);
        allLetters += e;
    }
}

void read(const std::string &amp;fname)
{
    std::ifstream ifs(fname);
    if (!ifs.is_open())
    {
        std::cout &lt;&lt; &quot;Cannot read input\n&quot;;
        exit(1);
    }
    std::string line;
    getline(ifs, line);
    letterBox.push_back(line);
    getline(ifs, line);
    letterBox.push_back(line);
    getline(ifs, line);
    letterBox.push_back(line);
    getline(ifs, line);
    letterBox.push_back(line);

    getAllLetters();
}
int side(char c)
{
    for (int k = 0; k &lt; 4; k++)
        if (std::find(letterBox[k].begin(), letterBox[k].end(), c) != letterBox[k].end())
            return k;
    throw std::runtime_error(
        &quot;side&quot;);
}
bool isWordInBox(const std::string &amp;word)
{
    // check all letters in word are somehere in box
    for (char c : word)
        if (std::find(
                allLetters.begin(),
                allLetters.end(),
                c) == allLetters.end())
            return false;

    // check consecutive letters are not in same side
    for (int k = 1; k &lt; word.size(); k++)
        if (side(word[k - 1]) == side(word[k]))
            return false;

    return true;
}

void filter()
{
    // open dictionary
    std::ifstream ifs(&quot;../dict/dictionary.txt&quot;);
    if (!ifs.is_open())
    {
        std::cout &lt;&lt; &quot;Cannot read dictionary\n&quot;;
        exit(1);
    }

    // read the dictionary words
    std::string line;
    while (getline(ifs, line))
    {
        // ignore two and three letter words
        if (line.size() &lt; 4)
            continue;

        // keep word if hidden in box
        if (isWordInBox(line))
            dict.push_back(line);
    }
    std::cout &lt;&lt; dict.size()
              &lt;&lt; &quot; words in box\n&quot;;
}

bool chain::hasAll()
{
    std::set&lt;char&gt; usedletters;
    for (const auto &amp;w : myChain)
        for (char c : w)
            usedletters.insert(c);
    if (usedletters.size() != allLetters.size())
        return false;

    // chain uses every letter in box
    // display
    for (const auto &amp;w : myChain)
        std::cout &lt;&lt; w &lt;&lt; &quot; &quot;;
    std::cout &lt;&lt; &quot;\n&quot;;

    return true;
}
bool chain::start(const std::string &amp;start)
{
    myChain.clear();
    myChain.push_back(start);
    myUsed.clear();
    used();

    return recurse();
}
void chain::used()
{
    for (char c : myChain.back())
        myUsed.insert(c);
}

bool chain::isUsedLetterInWord(const std::string &amp;word)
{
    // loop over letters, except first
    for (int k = 1; k &lt; word.size(); k++)
    {
        // check letter has been used earlier in chain
        if (myUsed.find(word[k]) != myUsed.end())
            return true;
    }
    return false;
}
bool chain::recurse()
{
    for (const auto &amp;w : dict)
    {
        // first letter must match last letter of previous word
        if (myChain.back().back() != *w.begin())
            continue;

        // no duplicate words in chain
        if (std::find(myChain.begin(), myChain.end(), w) != myChain.end())
            continue;

        // avoid already used letters, except first
        //
        // ( We are allowed to use letters more than once.
        //   However the shortest possible chain will use each letter only once )

        if( isUsedLetterInWord( w ))
            continue;

        // add to chain
        myChain.push_back(w);
        used();

        // Check for solution
        if (hasAll())
            return true;

        // look for next word to add to chain
        if (recurse())
            return true;
    }
    return false;
}

void findChain()
{
    // loop over words in filtered dictionary to start chain
    for (auto &amp;start : dict)
    {
        // recusive call to add words to chain
        if (theChain.start(start))
        {
            // solution found
            return;
        }
    }
    std::cout &lt;&lt; &quot;failed\n&quot;;
}

main(int c, char *argv[])
{
    raven::set::cRunWatch::Start();
    {
        raven::set::cRunWatch aWatcher(&quot;LBSolver&quot;);
        read(argv[1]);
        filter();
        findChain();
    }
    raven::set::cRunWatch::Report();
    return 0;
}
